import React, { useEffect, useRef } from 'react';

const BackgroundEffects = () => {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');

    let animationFrameId;
    let width = (canvas.width = window.innerWidth);
    let height = (canvas.height = window.innerHeight);

    const handleResize = () => {
      width = canvas.width = window.innerWidth;
      height = canvas.height = window.innerHeight;
    };
    window.addEventListener('resize', handleResize);

    // Deep purple neural particles & GitHub commit nodes
    const particleCount = Math.min(Math.floor(width / 20), 55);
    const particles = Array.from({ length: particleCount }, () => ({
      x: Math.random() * width,
      y: Math.random() * height,
      vx: (Math.random() - 0.5) * 0.3,
      vy: (Math.random() - 0.5) * 0.3,
      radius: Math.random() * 2 + 0.8,
      color: Math.random() > 0.4 ? '#635985' : (Math.random() > 0.5 ? '#443C68' : '#393053'),
      alpha: Math.random() * 0.6 + 0.25,
    }));

    const render = () => {
      ctx.clearRect(0, 0, width, height);

      // Draw deep purple neural & GitHub branch connections
      for (let i = 0; i < particles.length; i++) {
        const p1 = particles[i];
        p1.x += p1.vx;
        p1.y += p1.vy;

        if (p1.x < 0 || p1.x > width) p1.vx *= -1;
        if (p1.y < 0 || p1.y > height) p1.vy *= -1;

        ctx.beginPath();
        ctx.arc(p1.x, p1.y, p1.radius, 0, Math.PI * 2);
        ctx.fillStyle = p1.color;
        ctx.globalAlpha = p1.alpha;
        ctx.fill();

        for (let j = i + 1; j < particles.length; j++) {
          const p2 = particles[j];
          const dx = p1.x - p2.x;
          const dy = p1.y - p2.y;
          const dist = Math.sqrt(dx * dx + dy * dy);

          if (dist < 150) {
            ctx.beginPath();
            ctx.moveTo(p1.x, p1.y);
            ctx.lineTo(p2.x, p2.y);
            ctx.strokeStyle = '#635985';
            ctx.globalAlpha = (1 - dist / 150) * 0.22;
            ctx.lineWidth = 0.9;
            ctx.stroke();
          }
        }
      }

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    return () => {
      window.removeEventListener('resize', handleResize);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  return (
    <div className="fixed inset-0 pointer-events-none z-0 overflow-hidden">
      {/* Deep Purple Particle Canvas Layer */}
      <canvas ref={canvasRef} className="absolute inset-0 opacity-80" />

      {/* Grid Pattern Background */}
      <div className="absolute inset-0 bg-grid-scifi opacity-40" />

      {/* Deep Purple Ambient Radial Light Orbs */}
      <div className="absolute -top-40 left-1/4 w-[600px] h-[600px] bg-scifi-600/20 rounded-full blur-[140px] pointer-events-none animate-pulse-slow" />
      <div className="absolute top-1/3 -right-40 w-[500px] h-[500px] bg-scifi-700/25 rounded-full blur-[130px] pointer-events-none animate-float" />
      <div className="absolute -bottom-40 left-1/3 w-[700px] h-[700px] bg-scifi-800/40 rounded-full blur-[160px] pointer-events-none animate-float-reverse" />
    </div>
  );
};

export default BackgroundEffects;
